import sympy

def D(n):
    return n**3 + 4*n**2 + 6*n + 4

n_values = [5, 6, 7]
results = {}

for n in n_values:
    Dn = D(n)
    factors = sympy.factorint(Dn)
    results[n] = {
        "Dn": Dn,
        "factors": factors
    }

print("Results:")
for n, data in results.items():
    print(f"n={n}: D(n) = {data['Dn']}")
    print(f"  Prime factorization: {', '.join([f'{p}^{e}' for p, e in data['factors'].items()])}")
